/**
 * THE LABEL SNAPSHOT — byte for byte.
 *
 * `profile_ui.json` is generated by `scripts/gen_profile_ui.py`
 * from `profiles/geopolitics/profile.yaml`. The shell now reads its words from
 * it, so this file pins two things before anything moves a label:
 *
 *   1. every label string, verbatim, as a snapshot — a byte that changes fails
 *      here, never silently on the workstation;
 *   2. every label against the TypeScript literal it was exported from — the
 *      stance and mission labels, the map and read titles, the overview title,
 *      the unscoped label, the roster labels.
 *
 * And the absence rule: a key the profile does not declare renders the
 * PLATFORM noun, never a blank and never the exemplar's word.
 */
import { describe, expect, it } from 'vitest'
import raw from './profile_ui.json'
import {
  PLATFORM_NOUNS,
  PROFILE_UI,
  missionLabel,
  profileUiFrom,
  profileUnits,
  readTiers,
  rosterLabel,
  stanceLabel,
  subjectUnits,
} from './profileUi'
import { UNSCOPED_DESK_LABEL } from './morningReadBands'
import { PANEL_REGISTRY } from '@/panel-registry/registry'

const SOURCES = import.meta.glob(
  [
    '/src/panels/system/Wall.tsx',
    '/src/mobile/components/ReportsList.tsx',
    '/src/mobile/mobileModel.ts',
    '/src/panel-registry/registry.ts',
    '/src/lib/morningReadBands.ts',
    '/src/components/ObjectRail.tsx',
  ],
  { query: '?raw', import: 'default', eager: true },
) as Record<string, string>

describe('every label, byte for byte', () => {
  it('matches the snapshot taken before any label moved', () => {
    expect({
      schema: raw.schema,
      profile: raw.profile,
      subject: raw.subject,
      unit_noun: raw.unit_noun,
      frames: raw.frames.map((f) => [f.id, f.label]),
      top_floor: raw.top_floor,
      landing: raw.landing,
      stances: raw.stances.map((s) => [s.id, s.label, s.question]),
      missions: raw.missions.map((m) => [m.id, m.label]),
      map: raw.map,
      labels: raw.labels,
    }).toMatchInlineSnapshot(`
      {
        "frames": [
          [
            "world",
            "World",
          ],
          [
            "assessment",
            "Assessment",
          ],
          [
            "region",
            "Region",
          ],
          [
            "country",
            "Country",
          ],
          [
            "thematic",
            "Thematic",
          ],
        ],
        "labels": {
          "overview_title": "World at a glance",
          "read_title": "World Assessment",
          "roster": {
            "g20": "G20",
            "watch": "Watch list",
          },
          "unscoped_subject": "No desk (world / unscoped)",
        },
        "landing": "morning_read",
        "map": {
          "geometry": "iso2",
          "title": "World Map",
        },
        "missions": [
          [
            "morning_read",
            "Morning Read",
          ],
          [
            "desk_watch",
            "Desk Watch",
          ],
          [
            "crisis",
            "Crisis",
          ],
          [
            "release",
            "Release",
          ],
        ],
        "profile": "geopolitics",
        "schema": "legba/profile_ui/1",
        "stances": [
          [
            "morning_read",
            "Morning Read",
            "What happened, what moved, what does it mean?",
          ],
          [
            "desk",
            "Desk",
            "Everything about the one place or lane I have selected.",
          ],
          [
            "investigate",
            "Investigate",
            "Follow this one thing to the bottom.",
          ],
          [
            "trust",
            "Trust",
            "Is what it produced any good?",
          ],
          [
            "gate",
            "The Gate",
            "Work the human queues — journal proposals, grading, optimizer candidates.",
          ],
          [
            "engine",
            "Engine",
            "Is the machine running, and what is it configured as?",
          ],
        ],
        "subject": {
          "plural": "Desks",
          "singular": "Desk",
        },
        "top_floor": "world_assessor",
        "unit_noun": {
          "plural": "units",
          "singular": "unit",
        },
      }
    `)
  })

  // UI-B2 — THE INVERSION. The shell used to spell these strings and the
  // export was checked against them; now the shell READS the export, so each
  // surface renders the export's string and its source spells none of them.
  it('the map, read and overview titles and the unscoped label render the export', () => {
    expect(PANEL_REGISTRY['v4.map'].definition.defaultTitle).toBe(raw.map.title)
    expect(PANEL_REGISTRY['v4.assessment'].definition.defaultTitle).toBe(raw.labels.read_title)
    expect(UNSCOPED_DESK_LABEL).toBe(raw.labels.unscoped_subject)
    expect(SOURCES['/src/panels/system/Wall.tsx']).toContain('title={PROFILE_UI.labels.overview_title}')
    expect(SOURCES['/src/panel-registry/registry.ts']).toContain('PROFILE_UI.map.title')
    expect(SOURCES['/src/panel-registry/registry.ts']).toContain('PROFILE_UI.labels.read_title')
  })

  it('the roster labels render the export (the mobile list reads rosterLabel)', () => {
    expect(SOURCES['/src/mobile/components/ReportsList.tsx']).toContain('rosterLabel(roster)')
    for (const [tag, label] of Object.entries(raw.labels.roster)) expect(rosterLabel(tag)).toBe(label)
  })

  it('no source spells a profile label: the TS carries no label literal', () => {
    const literals = [
      raw.map.title,
      raw.labels.read_title,
      raw.labels.overview_title,
      raw.labels.unscoped_subject,
      ...Object.values(raw.labels.roster),
      ...raw.frames.map((f) => f.label),
    ]
    for (const [path, src] of Object.entries(SOURCES)) {
      for (const lit of literals) {
        expect(src.includes(`'${lit}'`) || src.includes(`"${lit}"`) || src.includes(`>${lit}<`), `${path}: ${lit}`).toBe(false)
      }
    }
  })

  it('the reader keeps every declared string exactly (no trimming, no re-casing)', () => {
    expect(PROFILE_UI.subject).toEqual(raw.subject)
    expect(PROFILE_UI.unit_noun).toEqual(raw.unit_noun)
    expect(PROFILE_UI.map.title).toBe(raw.map.title)
    expect(PROFILE_UI.labels.roster).toEqual(raw.labels.roster)
    expect(PROFILE_UI.rosters.units).toEqual(raw.rosters.units.map((u) => u.id))
  })
})

describe('the read tiers', () => {
  it('are the frames that carry a producer, top floor first', () => {
    const tiers = readTiers()
    expect(tiers[0].producer).toBe(raw.top_floor)
    expect(tiers.map((t) => t.id).sort()).toEqual(raw.frames.map((f) => f.id).sort())
  })
})

describe('THE ABSENCE RULE — an undeclared key renders the platform noun', () => {
  const bare = profileUiFrom({ schema: 'legba/profile_ui/1', profile: 'sanctions' })

  it('subject, unit, map and read nouns fall back to the platform', () => {
    expect(bare.subject).toEqual(PLATFORM_NOUNS.subject)
    expect(bare.unit_noun).toEqual(PLATFORM_NOUNS.unit)
    expect(bare.map).toEqual({ geometry: 'none', title: PLATFORM_NOUNS.map })
    expect(bare.labels.read_title).toBe(PLATFORM_NOUNS.read)
    expect(bare.labels.unscoped_subject).toBe(PLATFORM_NOUNS.unscoped)
  })

  it('no top floor, no unit roster, no stance or mission override — the shell keeps its own literal', () => {
    expect(bare.top_floor).toBeNull()
    expect(bare.rosters.units).toBeNull()
    expect(readTiers(bare)).toEqual([])
    expect(stanceLabel('desk', 'Desk', bare)).toBe('Desk')
    expect(missionLabel('crisis', 'Crisis', bare)).toBe('Crisis')
  })

  it('a roster tag with no label reads as the tag itself, never the exemplar word', () => {
    expect(rosterLabel('supply_chain', bare)).toBe('Supply chain')
    expect(rosterLabel('designated_party', bare)).toBe('Designated party')
  })

  it('never blank: an empty string is absent', () => {
    const blanky = profileUiFrom({ subject: { singular: '', plural: '  ' } })
    expect(blanky.subject).toEqual(PLATFORM_NOUNS.subject)
  })
})

describe('the unit roster (ROSTER-2) — one resolver, the profile’s words', () => {
  it('profileUnits() is the roster, in order, with the declared labels', () => {
    expect(profileUnits().map((u) => u.id)).toEqual(PROFILE_UI.rosters.units)
    for (const [u, declared] of profileUnits().map((p, i) => [p, raw.rosters.units[i]] as const)) {
      expect(u.label).toBe((declared as { label?: string }).label)
      expect(u.short).toBe((declared as { short?: string }).short)
    }
  })

  it('subjectUnits() drops only a unit scoped to an UNSCORED roster leg', () => {
    const ids = subjectUnits().map((u) => u.id)
    expect(ids).toEqual(PROFILE_UI.rosters.units!.filter((id) => id !== 'disruption_status'))
    // narrowed WITHIN the scored legs: kept, with its reason
    expect(subjectUnits().find((u) => u.id === 'proliferation_watch')?.scopeTag).toBe('nuclear_watch')
  })

  it('an undeclared label / glyph reads as the id itself, never another instance’s word', () => {
    const doc = {
      rosters: {
        subject_tags: ['regime', 'counterparty'],
        units: [{ id: 'designation_change' }, { id: 'licence_deadline', scope_tag: 'counterparty' }, { id: 'quota' }],
      },
    }
    const ui = profileUiFrom(doc)
    expect(profileUnits(ui)).toEqual([
      { id: 'designation_change', label: 'Designation change', short: 'DC', scopeTag: null, scopeNote: null, question: null },
      { id: 'licence_deadline', label: 'Licence deadline', short: 'LD', scopeTag: 'counterparty', scopeNote: null, question: null },
      { id: 'quota', label: 'Quota', short: 'QUO', scopeTag: null, scopeNote: null, question: null },
    ])
    // no scored legs declared: a unit scoped to a roster leg runs on that leg only
    expect(subjectUnits(ui).map((u) => u.id)).toEqual(['designation_change', 'quota'])
    expect(profileUnits(bareUi())).toEqual([])
  })
})

function bareUi() {
  return profileUiFrom({ schema: 'legba/profile_ui/1' })
}
